const recoverNotificationDeliveries = `-- name: RecoverNotificationDeliveries :many
SELECT id FROM hosting_notification_deliveries WHERE (state='pending' AND next_attempt_at<=clock_timestamp()) OR (state='sending' AND claim_expires_at<=clock_timestamp()) ORDER BY next_attempt_at,id LIMIT 100 FOR UPDATE SKIP LOCKED
`

func (q *Queries) RecoverNotificationDeliveries(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, recoverNotificationDeliveries)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

